<script lang="ts">
import {onMount} from 'svelte';import Toggle from './components/Toggle.svelte';import type {Catalog} from './locales';
let {t,request,onchanged}=$props<{t:Catalog;request:(url:string,body?:object)=>Promise<any>;onchanged:()=>Promise<void>}>();
type User={username:string;permissions:string[];enabled:boolean};
let users=$state<User[]>([]),username=$state(''),password=$state(''),enabled=$state(true),selected=$state<string[]>([]),superAdmin=$state(false),create=$state(true),busy=$state(false),error=$state(''),notice=$state('');let dialog:HTMLDialogElement;let deleting=$state('');
const keys=[['server.start','permServerStart'],['server.stop','permServerStop'],['server.restart','permServerRestart'],['server.force-stop','permServerForce'],['console.read','permConsoleRead'],['console.write','permConsoleWrite'],['logs.read','permLogsRead'],['bundles.read','permBundlesRead'],['bundles.start','permBundlesStart'],['bundles.stop','permBundlesStop'],['bundles.restart','permBundlesRestart'],['bundles.upload','permBundlesUpload'],['bundles.build','permBundlesBuild'],['settings.write','permSettings'],['users.manage','permUsers']] as const;
function edit(user?:User){superAdmin=!!user&&keys.every(([p])=>user.permissions.includes(p));username=user?.username??'';password='';selected=[...(user?.permissions??[])];enabled=user?.enabled??true;create=!user;notice='';error='';}
async function load(){users=await request('/api/users');}
async function run(fn:()=>Promise<void>){busy=true;error='';notice='';try{await fn();}catch(e){error=(e as Error).message;}finally{busy=false;}}
async function save(e:SubmitEvent){e.preventDefault();await run(async()=>{await request('/api/users/save',{username,password:password||null,permissions:selected,enabled,create});password='';notice='userSaved';await onchanged();await load();create=false;});}
async function remove(){dialog.close();await run(async()=>{await request('/api/users/delete',{username:deleting});notice='userDeleted';await onchanged();await load();if(deleting===username)edit();});}
onMount(()=>{run(load);});
</script>
<div class="users-layout">
<section class="users-list"><div class="section-heading"><h2>{t.users}</h2><button onclick={()=>edit()} disabled={busy}>{t.addUser}</button></div><ul>{#each users as user}<li class:selected={!create&&username===user.username}><button class="user-row" disabled={busy} onclick={()=>edit(user)} aria-label={t.editUser+': '+user.username}><strong>{user.username}</strong><small>{user.enabled?t.enabled:t.stopped}</small></button><button disabled={busy} onclick={()=>{deleting=user.username;dialog.showModal();}}>{t.deleteUser}</button></li>{/each}</ul></section>
<form class="user-editor" onsubmit={save}><h2>{create?t.addUser:t.editUser}</h2><div class="user-fields"><label>{t.username}<input bind:value={username} disabled={!create||busy} required minlength="3" maxlength="32" autocomplete="off"/></label><label>{create?t.password:t.newPassword}<input type="password" bind:value={password} required={create} minlength="8" maxlength="256" autocomplete="new-password" disabled={busy}/></label></div><Toggle label={t.enabled} checked={enabled} disabled={busy} onchange={v=>enabled=v}/><h2>{t.permissions}</h2><Toggle label={t.superAdmin} checked={superAdmin} disabled={busy} onchange={v=>{superAdmin=v;if(v)selected=keys.map(([p])=>p);}}/><p class="muted">{t.superAdminHint}</p><div class="permission-grid">{#each keys as [permission,label]}<Toggle label={t[label]} checked={selected.includes(permission)} disabled={busy||superAdmin} onchange={value=>{selected=value?[...selected,permission]:selected.filter(p=>p!==permission);}}/>{/each}</div><p class="muted">{t.consolePermissionHint}</p>{#if error}<p role="alert" class="error">{t.errors[error as keyof typeof t.errors]??t.errors['request.failed']}</p>{/if}{#if notice}<p role="status" class="notice">{t[notice as 'userSaved'|'userDeleted']}</p>{/if}<button class="primary" disabled={busy}>{t.saveUser}</button></form>
</div>
<dialog bind:this={dialog}><h2>{t.deleteUser}: {deleting}</h2><p>{t.deleteUserBody}</p><div class="actions"><button onclick={()=>dialog.close()}>{t.cancel}</button><button class="danger" onclick={remove}>{t.deleteUser}</button></div></dialog>
